 // "4월 3, 2026" 형태
 if(/^\d{1,2}월\s*\d{1,2}[,，]\s*\d{4}$/.test(t)){
 var p=t.match(/^(\d{1,2})월\s*(\d{1,2})/);
 if(p){el.textContent=p[1]+'월 '+p[2]+'일';}
 return;
 }
 // "4월 3" 형태 (월일만)
 if(/^\d{1,2}월\s*\d{1,2}$/.test(t)){
 var p=t.match(/^(\d{1,2})월\s*(\d{1,2})/);
 if(p){el.textContent=p[1]+'월 '+p[2]+'일';}
 }
 });
 // 3. 읽기시간
 document.querySelectorAll('.nyt-post-read,.kth-post-read').forEach(function(el){
 var m=(el.textContent||'').match(/(\d+)/);
 if(m){el.textContent=m[1]+'분 읽기';}
 });
